import math

def line_equation(x1, y1, x2, y2):
    return (y2 - y1) / (x2 - x1)

def in_triangle(p, A, B, C):
    cross_product = (line_equation(A[0], B[0], C[0], A[0]) * (A[0] - p[0]) + line_equation(A[1], B[1], C[1], A[1]) * (A[1] - p[1])) * (A[0] - C[0]) * (B[0] - C[0]) - (line_equation(A[0], B[0], C[0], A[0]) * (A[1] - p[1]) + line_equation(A[1], B[1], C[1], A[1]) * (A[0] - p[0])) * (A[1] - C[1]) * (B[1] - C[1])
    return cross_product >= 0

def min_time_of_fall(p1, p2, v1, v2, fdown, u, time_park):
    horizontal_speed_product = time_park * v1[0] * v2[0]
    vertical_speed_product = time_park * v1[1] * v2[1]
    time_fall = math.sqrt(horizontal_speed_product / (fdown + v2[1] * p2[1] * (fdown - v1[1] * p1[1] * math.sin(math.atan2(u[1], u[0]))[1])) \
                         + vertical_speed_product / fdown)
    return time_park + time_fall, time_park + time_fall

def find_min_time(A, V, Fdown, U):
    min_t1 = float('inf')
    min_t2 = float('inf')
    for i in range(len(A)):
        for j in range(i + 1, len(A)):
            t1, t2 = min_time_of_fall(A[0], A[1], V, (V[0], V[1], math.inf), Fdown, (U[0], U[1], U[2] - Fdown), None)
            if t1 < min_t1:
                min_t1 = t1
                min_t2 = t2
            else:
                if abs(t2 - min_t2) < 1e-6:
                    min_t2 = math.min(min_t2, t2)
            if t1 is not None and t2 is not None:
                break
        else:
            continue
        break
    if min_t1 is not None and min_t2 is not None:
        return min_t1, min_t2
    elif min_t1 is not None:
        return min_t1, None
    elif min_t2 is not None:
        return None, min_t2
    else:
        return -1, -1

