from collections import deque

def paint_ribbon(n, m, operations):
    # Initialize the coloring and colorfulness arrays
    colors = [0] * n
    colorfulness = [0] * n

    # Event queue to manage painting and colorfulness computation
    events = deque()

    for operation in operations:
        type_ = operation[0]
        if type_ == 1:
            l, r, x = operation[1], operation[2], operation[3]
            for i in range(l-1, r):
                events.appendleft((i, i, x))
                events.appendleft((i, i + 1, -1))
        else:
            l, r = operation[1], operation[2]
            i, j = l-1, r
            next_event = (i, i, x)
            while events:
                if events[0][0] == i:
                    colorfulness[events.popleft()[1]] += abs(x - colors[i - 1])
                    break
                elif events[0][1] == j:
                    colorfulness[events.popleft()[1]] -= abs(x - colors[j - 1])
                    break
                else:
                    while events[0][2] == -1 and i < events[0][0]:
                        i += 1
                        next_event = (i, i, x)
            events.appendleft(next_event)

    return sum(colorfulness)

