            for key, val in orbit_1.items():
                if val == '.': continue
                for i, j in orbit_1.values():
                    if not changes.issuperset({i+1, j, i-1, j+1}): 
                        changes |= {(i+1, j), (i-1, j), (i, j+1), (i, j-1)}
            orbit |= changes
            orbits |= changes

    return sum(v * v for v in orbits.values())
