def two_pointed_angle(p0, p1, p2, p3):
    return math.atan2(p3[1] - p2[1], p3[0] - p2[0]) - math.atan2(p1[1] - p0[1], p1[0] - p0[0])

def line_over_point(m1, d1, m2, d2, x, y):
    m1, d1, m2, d2 = map(float, str(m1) + str(d1))
    m3, d3 = map(float, str(m2) + str(d2))
    if m1 == m2 and (m1 != m3 or (d3 - d2) > 0): 
        return False
    return (y - d1) * (1 / m1) - (x - d2) * (1 / m2) >= 0

