def prime_factors(n):
    i = 2
    factors = {}
    while i * i <= n:
        while (n % i) == 0:
            if i in factors:
                factors[i] += 1
            else:
                factors[i] = 1
            n //= i
        i += 1
    if n > 1:
        factors[n] = 1

    return factors

def lcm_list(numbers):
    result = 1
    for number in numbers:
        factors = prime_factors(number)
        for prime, power in factors.items():
