from collections import defaultdict

def find(parents, i):
    if parents[i] == i:
        return i
    return find(parents, parents[i])

def union(parents, ranks, i, j):
    rootI = find(parents, i)
    rootJ = find(parents, j)
    if rootI != rootJ:
        if ranks[rootI] < ranks[rootJ]:
            parents[rootI] = rootJ
        elif ranks[rootI] > ranks[rootJ]:
            parents[rootJ] = rootI
        else:
            parents[rootJ] = rootI
            ranks[rootI] += 1

def calculate_spanning_tree(n, m, k, edges):
    graph = defaultdict(list)
    ranking = defaultdict(int)
    for u, v, weight in edges:
        graph[u-1].append((v-1, weight))
        graph[v-1].append((u-1, weight))
        ranking[u-1] += (1 if u == 1 else 0)
        ranking[v-1] += (1 if v == 1 else 0)

    sorted_edges = sorted(ranking.items(), key=lambda x: x[1])
    total_mst_weight = 0
    used_edges = 0

    for _, weight in sorted_edges:
        for dest, _ in graph[u]:
            union(parents, ranks, u, dest)
        if used_edges == k:
            break
        for dest, iweight in graph[u]:
            if find(parents, u) != find(parents, dest) and find(parents, dest) != find(parents, u):
                total_mst_weight += weight - iweight
                union(parents, ranks, u, dest)
                used_edges += 1

    return used_edges, total_mst_weight

