from collections import defaultdict, deque

def find_parent(parent, i):
    if parent[i] != i:
        parent[i] = find_parent(parent, parent[i])
    return parent[i]

def union_parent(parent, a, b):
    a = find_parent(parent, a)
    b = find_parent(parent, b)
    if a < b:
        parent[b] = a
    else:
        parent[a] = b

def is_connected(city, parent):
    if parent[city] == city:
        return True
    return False

def get_spanning_tree(mst, parent, k, first_city):
    broken = 0
    queue = deque([first_city])
    while queue and broken < k and len(mst) < 5000:
        city = queue.pop()
        for neighbor in mst.get(city, []):
            if not is_connected(neighbor, parent):
                union_parent(parent, city, neighbor)
                queue.append(neighbor)
                broken += 1
    if broken == k:
        return len(mst)
    return -1

def main():
